const NL = String.fromCharCode(10);
const b = ($input.first().json.body) || $input.first().json || {};
const g = (k, d = '') => (b[k] == null || b[k] === '' ? d : String(b[k]));
const topic = g('topic', g('theme', ''));
const account = g('account', '');
const industry = g('industry', '');
const theme = g('theme', '');
const objective = g('objective', '');
const url = g('tracked_url', '');
const lines = [
  'Write a LinkedIn post (broadcast, for a feed — not a 1:1 message).',
  topic ? ('Topic: ' + topic) : 'Topic: a relevant B2B insight',
  account ? ('Context — account/theme this relates to: ' + account + (industry ? (' (industry: ' + industry + ')') : '')) : '',
  theme ? ('Angle/theme: ' + theme) : '',
  objective ? ('Business objective it should support: ' + objective) : '',
  url ? ('Include this link naturally near the end: ' + url) : '',
  'Write the post now.'
].filter(Boolean);
return [{ json: { prompt: lines.join(NL), topic: topic, account: account, tracked_url: url } }];

const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const out = $json.output || '';
const bp = $('Build Post Prompt').first().json;
return [{ json: { body_esc: esc(out), account_esc: esc(bp.account), topic_esc: esc(bp.topic), url_esc: esc(bp.tracked_url) } }];

const crypto = require('crypto');
const SECRET = $('Get HMAC Secret').first().json.value;
const row = $('Insert Post').first().json;
const id = row.id;
function sign(a) { return crypto.createHmac('sha256', SECRET).update('linkedin_post:' + id + ':' + a).digest('hex').slice(0, 32); }
const base = 'https://designprodigy.app.n8n.cloud/webhook/linkedin-post-approval';
const NL = String.fromCharCode(10);
const subject = 'LinkedIn post ready for approval' + (row.account ? (' — ' + row.account) : '');
const parts = [];
parts.push('Draft LinkedIn post' + (row.topic ? (' on: ' + row.topic) : '') + (row.account ? (' (account: ' + row.account + ')') : '') + ':');
parts.push('');
parts.push(row.post_body || '');
if (row.tracked_url) parts.push('Link to include: ' + row.tracked_url);
parts.push('');
parts.push('APPROVE (you will then post it to LinkedIn yourself): ' + base + '?id=' + id + '&action=approve&sig=' + sign('approve'));
parts.push('REJECT: ' + base + '?id=' + id + '&action=reject&sig=' + sign('reject'));
return [{ json: { subject: subject, message: parts.join(NL) } }];
